Parameters: {"file_path":"/repo/ErrorBoundary.tsx","content":"import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return (
      <div role="alert" style={{ padding: "1rem", border: "1px solid #f87171", borderRadius: 4 }}>
        <h2 style={{ marginTop: 0 }}>Something went wrong</h2>
        <pre style={{ fontSize: "0.85em", whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
          {error.message}
        </pre>
        <button onClick={this.reset}>Retry</button>
      </div>
    );
  }
}
"}

